    def delete(
        self,
        id: str,
        *,
        confirm: Literal[True],
        end_user_id: str | None = None,
        conductor_end_user_id: str | None = None,
        idempotency_key: str | None = None,
        timeout: float | None = None,
        total_timeout: float | None = None,
        max_retries: int | None = None,
        server_timeout: int | None = None,
    ) -> VendorDeleted:
        """Delete a vendor.

        Asks QuickBooks to delete a vendor (qbXML ListDel). QuickBooks refuses to delete vendors that transactions or other records still use (`409 QBD_OBJECT_IN_USE`). While the company file is open in multi-user mode, QuickBooks can accept the delete but keep the vendor, inactive and readable by its ID; single-user mode permits removal, but success depends on the record type and its dependencies. Customer removal was verified on Enterprise 24. The API reads the vendor back in the same request, so `deleted` is true only when QuickBooks no longer returns it; otherwise `deleted` is false, `deactivated` and `isActive` say what QuickBooks kept, and `retainedBecause` is `multi_user_mode` when that was the reason. Treat a kept vendor as not deleted: it still counts as a name in use. `deleted` is null when the read-back failed (warning `QBD_DELETE_NOT_VERIFIED`); QuickBooks accepted the delete, but removal is unverified, so inspect the record before making another write. Prefer deactivating: updating the vendor with `isActive: false` keeps its history and hides it from lists. Send `confirm=true` to show the deletion is intended; without it the API answers `400 INVALID_PARAMETER` and sends nothing. QuickBooks lists deleted objects through the deleted-list-objects list for 90 days. Send an `Idempotency-Key` to make retries safe.

        Operation ``qbd.vendors.delete``: ``DELETE /v1/quickbooks-desktop/vendors/{id}``.

        Args:
            id: QuickBooks ID of the vendor.
            confirm: Must be true: confirms that you intend this permanent change to the vendor. Any other value is refused with 400 INVALID_PARAMETER and nothing is sent to QuickBooks. Send it as `confirm=true`.
            end_user_id: End user (``eu_...``) whose QuickBooks company file to use. Defaults to the client's ``end_user_id``.
            conductor_end_user_id: Alias of ``end_user_id`` with Conductor's name, for code ported from ``conductor-py``. Passing both with different values raises ``DaapiError``.
            idempotency_key: Makes the write safe to retry (``Idempotency-Key``). Defaults to a new UUID that is reused on every retry of this call.
            timeout: Client-side timeout in seconds for each HTTP attempt; also the time budget for waiting on a request that is still running in QuickBooks. Defaults to the client's ``timeout``.
            total_timeout: Time budget in seconds for the whole call: every attempt, retry backoff and the wait for a pending request. Defaults to the client's ``total_timeout`` (none).
            max_retries: Retries for network errors, 429 and retryable 5xx responses. Defaults to the client's ``max_retries``.
            server_timeout: Seconds the API waits for QuickBooks before answering (``Daapi-Timeout-Seconds``, 1-300). Defaults to the client's ``server_timeout`` or the API default.

        Returns:
            The VendorDeleted object.
        """
        return self._client._request(
            _QBD_VENDORS_DELETE,
            "DELETE",
            "/v1/quickbooks-desktop/vendors/" + _pp("id", id),
            cast_to=VendorDeleted.from_wire,
            query={
                "confirm": confirm,
            },
            end_user_id=end_user_id,
            conductor_end_user_id=conductor_end_user_id,
            idempotency_key=idempotency_key,
            timeout=timeout,
            total_timeout=total_timeout,
            max_retries=max_retries,
            server_timeout=server_timeout,
        )

